export const isOrderForVendor = (order, vendor) => {
  if (!order || !vendor) return false;
  const vId = String(vendor.id || '').toLowerCase().trim();
  const vUser = String(vendor.username || '').toLowerCase().trim();
  const vBiz = String(vendor.businessName || '').toLowerCase().trim();
  const vName = String(vendor.name || '').toLowerCase().trim();

  // Critical requirement: Orders pending admin approval or without explicit vendor assignment must NOT be shown to vendors!
  if (order.status === 'Pending' || order.stage === 'pending' || !order.assignedVendorId) {
    return false;
  }

  // 1. Explicitly assigned vendor ID or username
  const assignedId = String(order.assignedVendorId || '').toLowerCase().trim();
  if (assignedId && (assignedId === vId || assignedId === vUser || (vId && assignedId === vId))) return true;

  // 2. Assigned vendor name matches
  const assignedName = String(order.assignedVendorName || '').toLowerCase().trim();
  if (assignedName && (assignedName === vBiz || assignedName === vName)) return true;

  return false;
};

// High-Resonance Web Audio Alert Synthesizer
// Synthesizes a loud, sustained, luxurious "TIIIIIIIIINNNNNGGGGG..." alert (or resonant buzz)
export const playNewOrderAlertSound = (style = 'ting') => {
  if (typeof window === 'undefined') return;
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) {
      const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
      audio.play().catch(() => {});
      return;
    }

    const ctx = new AudioCtx();
    if (ctx.state === 'suspended') {
      ctx.resume().catch(() => {});
    }

    const now = ctx.currentTime;
    const master = ctx.createGain();
    master.gain.setValueAtTime(0.85, now);
    master.connect(ctx.destination);

    // Initial sharp attack ping (E5 - 659.25 Hz)
    const oscIntro = ctx.createOscillator();
    const gainIntro = ctx.createGain();
    oscIntro.type = 'sine';
    oscIntro.frequency.setValueAtTime(659.25, now);
    gainIntro.gain.setValueAtTime(0.45, now);
    gainIntro.gain.exponentialRampToValueAtTime(0.001, now + 0.28);
    oscIntro.connect(gainIntro);
    gainIntro.connect(master);
    oscIntro.start(now);
    oscIntro.stop(now + 0.3);

    // Sustained Bell Chime ("TIIIIIIIIINNNNNGGGGGG...")
    // 1. Fundamental A5 (880 Hz) - long 2.5 second resonant decay
    const osc1 = ctx.createOscillator();
    const gain1 = ctx.createGain();
    osc1.type = 'sine';
    osc1.frequency.setValueAtTime(880, now + 0.04);
    osc1.frequency.exponentialRampToValueAtTime(878, now + 2.5); // acoustic metallic micro-detune
    gain1.gain.setValueAtTime(0.001, now);
    gain1.gain.setValueAtTime(0.85, now + 0.04);
    gain1.gain.exponentialRampToValueAtTime(0.001, now + 2.6);
    osc1.connect(gain1);
    gain1.connect(master);
    osc1.start(now + 0.04);
    osc1.stop(now + 2.65);

    // 2. First Harmonic A6 (1760 Hz) - crystalline octave ring
    const osc2 = ctx.createOscillator();
    const gain2 = ctx.createGain();
    osc2.type = 'sine';
    osc2.frequency.setValueAtTime(1760, now + 0.04);
    gain2.gain.setValueAtTime(0.001, now);
    gain2.gain.setValueAtTime(0.45, now + 0.04);
    gain2.gain.exponentialRampToValueAtTime(0.001, now + 2.1);
    osc2.connect(gain2);
    gain2.connect(master);
    osc2.start(now + 0.04);
    osc2.stop(now + 2.15);

    // 3. Second Harmonic E7 (2640 Hz) - sparkling metallic ting strike
    const osc3 = ctx.createOscillator();
    const gain3 = ctx.createGain();
    osc3.type = 'triangle';
    osc3.frequency.setValueAtTime(2640, now + 0.04);
    gain3.gain.setValueAtTime(0.001, now);
    gain3.gain.setValueAtTime(0.35, now + 0.04);
    gain3.gain.exponentialRampToValueAtTime(0.001, now + 1.2);
    osc3.connect(gain3);
    gain3.connect(master);
    osc3.start(now + 0.04);
    osc3.stop(now + 1.25);

    // 4. High shimmer overtone (3520 Hz)
    const osc4 = ctx.createOscillator();
    const gain4 = ctx.createGain();
    osc4.type = 'sine';
    osc4.frequency.setValueAtTime(3520, now + 0.04);
    gain4.gain.setValueAtTime(0.001, now);
    gain4.gain.setValueAtTime(0.18, now + 0.04);
    gain4.gain.exponentialRampToValueAtTime(0.001, now + 0.8);
    osc4.connect(gain4);
    gain4.connect(master);
    osc4.start(now + 0.04);
    osc4.stop(now + 0.85);

  } catch (e) {
    console.warn('Audio alert could not play:', e);
  }
};

