  const handleExportData = async () => {
    const data = await db.exportDatabase();
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `giftportal_backup_${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast('Database exported successfully!');
  };

  const handleTestPaymentWebhook = async (isDuplicate = false) => {
    setIsTestingWebhook(true);
    try {
      const paymentId = isDuplicate && lastTestedPaymentId ? lastTestedPaymentId : `pay_test_${Date.now()}`;
      if (!isDuplicate) setLastTestedPaymentId(paymentId);

      const payload = {
        event: 'payment.captured',
        paymentId,
        idempotencyKey: `idemp_${paymentId}`,
        orderData: {
          id: `${Math.floor(1000 + Math.random() * 9000)}`,
          total: 1499,
          paymentMethod: 'Razorpay UPI',
          customerName: 'Aarav Sharma (Webhook Test)',
          customerMobile: '9876543210',
          cart: [{ id: products[0]?.id || 'flower-1', name: products[0]?.name || 'Velvet Crimson Rose Box', qty: 1, price: 1499 }],
          recipient: { name: 'Meera Sharma', city: 'Indore', area: 'Vijay Nagar', street: 'Sector B' }
        }
      };

      const res = await fetch('/api/webhooks/payment', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-webhook-signature': 'test_signature'
        },
        body: JSON.stringify(payload)
      });
      const data = await res.json();
      setWebhookTestResult(data);
      if (data.idempotent) {
        showToast('Duplicate webhook blocked by idempotency filter! No duplicate order created.');
      } else {
        showToast(`Payment captured! Order #${data.orderId} created successfully.`);
        const freshOrders = await db.getOrders();
        setOrders(freshOrders);
      }
    } catch (err) {
      console.error(err);
      setWebhookTestResult({ error: err.message });
      showToast('Webhook test failed', 'error');
    } finally {
      setIsTestingWebhook(false);
    }
  };

