                      const hasB2B = p.targetMarket === 'b2b' || p.targetMarket === 'both' || p.b2bPrice;
                      if (!hasB2B) return false;
                      if (b2bCategoryFilter !== 'All' && p.cat !== b2bCategoryFilter) return false;
                      if (b2bSearchQuery.trim()) {
                        const q = b2bSearchQuery.toLowerCase();
                        return (p.name || '').toLowerCase().includes(q) || (p.cat || '').toLowerCase().includes(q) || (p.vendorName || '').toLowerCase().includes(q);
                      }
                      return true;
